# 用电安全实验台
dev = 1   # 同时接入的电器数

hide()
w = 800
if dev == 2:
    w = 2000
if dev == 3:
    w = 3200
if dev == 4:
    w = 5200
names = ""
fill_rect(0, 130, 360, 30, "#1d4ed8")
write("插线板负载 " + w + " W（额定 2500W）", 0, 130, "#fff", 12)
fill_rect(-160, 60, 320, 40, "#e2e8f0")
over = w / 2500
if over > 1:
    fill_rect(-160, 60, 320, 40, "#dc2626")
if over <= 1:
    fill_rect(-160, 60, w / 2500 * 320, 40, "#16a34a")
write("功率条", -100, 60, "#fff", 12)
if dev >= 1:
    write("电饭煲 800W", -130, 20, "#0f172a", 10)
if dev >= 2:
    write("+ 微波炉 1200W", -10, 20, "#0f172a", 10)
if dev >= 3:
    write("+ 电暖器 1200W", 110, 20, "#0f172a", 10)
if dev >= 4:
    write("+ 电磁炉 2000W", 0, -5, "#0f172a", 10)
if w > 2500:
    fill_rect(0, -45, 360, 34, "#fef2f2")
    write("超载！电线发烫，可能起火 —— 快拔掉一个", 0, -45, "#dc2626", 11)
if w <= 2500:
    fill_rect(0, -45, 360, 34, "#f0fdf4")
    write("负载安全 ✓ 大功率电器分开插", 0, -45, "#16a34a", 11)
write("安全守则：湿手不碰电·插头拔不拽线·雷雨拔电器", 0, -90, "#7c3aed", 10)

